const grammar={
  'Present simple vs present continuous':{r:['Present simple = routines, facts and permanent situations.','Present continuous = actions happening now, temporary situations and changing situations.','State verbs such as know, need, understand and believe are normally not continuous.'],s:'usually / every day → present simple · now / at the moment / this week → present continuous',e:['I usually work from home on Fridays.','I’m working from the office this week.','I understand the instructions.'],t:'Not “I am understanding”. Use “I understand” for a state.'},
  'Past simple vs present perfect':{r:['Past simple = finished past action with a finished time reference.','Present perfect = experience, recent result, or a period still open.','Form: have/has + past participle.'],s:'yesterday / last week / in 2025 → past simple · already / yet / ever / since / for → present perfect',e:['I sent the invoice yesterday.','I’ve already sent the invoice.','We have worked together for three years.'],t:'Do not use present perfect with a finished time marker such as yesterday.'},
  'Past continuous & interrupted actions':{r:['Past continuous = action in progress at a past moment.','Past simple = shorter completed event that interrupts or occurs during it.','Use while with a longer background action; when often introduces the shorter event.'],s:'while → often past continuous · when → often past simple',e:['I was speaking to a client when the system stopped.','While we were travelling, the weather changed.'],t:'Use was/were + verb-ing: was working, were waiting.'},
  'Future forms':{r:['will = instant decisions, predictions, offers.','be going to = prior intentions/plans.','present continuous = arranged appointments.','present simple = timetables/schedules.'],s:'I think / probably → will · plan → going to · arrangement → present continuous · timetable → present simple',e:['I’ll call her now.','We’re going to update the website.','I’m meeting the client at 2.','The train leaves at 18:05.'],t:'A neutral timetable normally uses present simple.'},
  'Modals':{r:['can = ability/permission; could = past ability or polite request; should = advice; must/have to = obligation.','After a modal, use the base verb without to.'],s:'advice → should · obligation → must/have to · polite request → could',e:['Could you send me the file?','You must wear a badge.','We have to finish by Friday.'],t:'Not “must to wear” or “can to help”.'},
  'Conditionals':{r:['Zero: if + present, present for facts/procedures.','First: if + present, will + base for realistic future results.','Second: if + past, would + base for hypothetical situations.'],s:'fact → zero · real future → first · hypothetical → second',e:['If the alarm sounds, leave the building.','If the delivery is late, I’ll call.','If I had more time, I would take a longer course.'],t:'First conditional: If it rains, we will cancel — not if it will rain.'},
  'Questions & auxiliaries':{r:['Present simple questions: do/does + subject + base.','Past simple questions: did + subject + base.','With be/modals, invert directly.','Indirect questions keep statement word order.'],s:'Do/Does + base · Did + base · Could you tell me + statement order',e:['Do you work on Saturdays?','When did the problem start?','Could you tell me where the station is?'],t:'Not “Could you tell me where is the station?”'},
  'Articles & countability':{r:['a/an = one non-specific singular countable noun.','the = specific/known item.','No article = general plural/uncountable idea.','much = uncountable; many = countable plural.'],s:'one general item → a/an · specific known item → the · general plural → no article',e:['I need a receipt.','Where is the receipt?','Information is important.','How many emails did you receive?'],t:'Information, advice, equipment and luggage are uncountable.'},
  'Prepositions':{r:['at = exact time; on = day/date; in = month/year/long period.','for = duration; since = starting point.','at/in/on also vary by place and transport context.'],s:'at 9:30 · on Monday · in August · for two hours · since 2024',e:['The meeting is at 10 on Tuesday.','She works in Nantes.','I’ve been here for two hours.'],t:'on time = punctual; in time = early enough.'},
  'Comparatives & superlatives':{r:['Short adjectives: -er / -est. Longer adjectives: more / most.','Use than after a comparative.','as + adjective + as = equality.','Irregular: good → better → best.'],s:'than → comparative · the + group → superlative',e:['This option is cheaper than the first.','It is the most convenient solution.','The new system is as reliable as the old one.'],t:'Not “more easier”; say “easier”.'},
  'Relative clauses':{r:['who = people; which = things; where = places; that can replace who/which in many defining clauses.','A defining clause identifies the person or thing.'],s:'person → who · thing → which/that · place → where',e:['The colleague who called is in Finance.','This is the file that I need.','That’s the office where the meeting takes place.'],t:'For a place relationship: “the hotel where we stayed”.'},
  'Passive voice':{r:['Use the passive when the action/result is more important than the person doing it.','Form: be in the correct tense + past participle.','Common in procedures, rules, reports and formal workplace English.'],s:'is/are + past participle · was/were + past participle · will be + past participle',e:['The order was delivered yesterday.','All requests are reviewed within 48 hours.','The report will be sent tomorrow.'],t:'The tense is carried by be: was sent, is checked, will be completed.'},
  'Adverbs & word order':{r:['Frequency adverbs usually go before the main verb but after be.','Manner adverbs often follow the verb/object.','Place generally comes before time at the end of a sentence.'],s:'usually/often/never · carefully/quickly · at the office / on Monday',e:['I usually check my messages at 9.','She is often available in the afternoon.','Please complete the form carefully.'],t:'Not “I check usually”. Say “I usually check”.'}
};
